export const SEGMENTS = SEGMENT_DATA;

export const startFrame = (seg: Segment): number => Math.round(seg.startSec * FPS);
export const endFrame = (seg: Segment): number => Math.round(seg.endSec * FPS);
export const segmentFrames = (seg: Segment): number => endFrame(seg) - startFrame(seg);

export const OUTRO_START_SEC = NARRATION_SECONDS;

export const segmentAtFrame = (frame: number): Segment | null => {
  for (const seg of SEGMENTS) {
    if (frame >= startFrame(seg) && frame < endFrame(seg)) return seg;
  }
  return null;
};
